// Workflow run status: one Run machine per run id, created by start (generated by scripts/gen.mjs).
import { module, enumType, machine, field, t, action, on, require, set, when, terminal, invariant, implies, isIn } from '@cognitive-fab/poly/embed';

export default module('workflow', [
  enumType('Status', ['queued', 'running', 'evicted', 'completed', 'failed', 'cancelled']),
  machine('Run', {
    state: {
      status: field(t.named('Status'), ($) => $.queued),
      started: field(t.bool, () => false),
      task0: field(t.named('Status'), ($) => $.queued),
      task1: field(t.named('Status'), ($) => $.queued),
      task2: field(t.named('Status'), ($) => $.queued),
    },
    items: [
      terminal(($) => isIn($.status, [$.completed, $.failed, $.cancelled])),
      action('Start', {}),
      action('TaskStarted', { task: t.int.check([0, 1, 2], 'strict') }),
      action('TaskCompleted', { task: t.int.check([0, 1, 2], 'strict') }),
      action('TaskFailed', { task: t.int.check([0, 1, 2], 'strict') }),
      action('TaskEvicted', { task: t.int.check([0, 1, 2], 'strict') }),
      action('TaskRequeued', { task: t.int.check([0, 1, 2], 'strict') }),
      action('Cancel', {}),
      on('Start', ($) => [require(!$.started, 'run-exists'), set('started', true)]),
      on('TaskStarted', ($) => [
        require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.failed, $.cancelled]), 'run-finished'),
        when($.task === 0, [require($.task0 === $.queued, 'not-queued'), set('task0', $.running), when($.task1 === $.running && $.task2 === $.running, [set('status', $.running)], [when($.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.running)])])],
          [when($.task === 1, [require($.task1 === $.queued, 'not-queued'), set('task1', $.running), when($.task0 === $.running && $.task2 === $.running, [set('status', $.running)], [when($.task0 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.running)])])],
            [require($.task2 === $.queued, 'not-queued'), set('task2', $.running), when($.task0 === $.running && $.task1 === $.running, [set('status', $.running)], [when($.task0 === $.failed || $.task1 === $.failed, [set('status', $.failed)], [set('status', $.running)])])])]),
      ], ['task']),
      on('TaskCompleted', ($) => [
        require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.failed, $.cancelled]), 'run-finished'),
        when($.task === 0, [require($.task0 === $.running, 'not-running'), set('task0', $.completed), when($.task1 === $.completed && $.task2 === $.completed, [set('status', $.completed)], [when($.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [when(isIn($.task1, [$.queued, $.running, $.evicted]) || isIn($.task2, [$.queued, $.running, $.evicted]), [set('status', $.running)], [set('status', $.cancelled)])])])],
          [when($.task === 1, [require($.task1 === $.running, 'not-running'), set('task1', $.completed), when($.task0 === $.completed && $.task2 === $.completed, [set('status', $.completed)], [when($.task0 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [when(isIn($.task0, [$.queued, $.running, $.evicted]) || isIn($.task2, [$.queued, $.running, $.evicted]), [set('status', $.running)], [set('status', $.cancelled)])])])],
            [require($.task2 === $.running, 'not-running'), set('task2', $.completed), when($.task0 === $.completed && $.task1 === $.completed, [set('status', $.completed)], [when($.task0 === $.failed || $.task1 === $.failed, [set('status', $.failed)], [when(isIn($.task0, [$.queued, $.running, $.evicted]) || isIn($.task1, [$.queued, $.running, $.evicted]), [set('status', $.running)], [set('status', $.cancelled)])])])])]),
      ], ['task']),
      on('TaskFailed', ($) => [
        require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.failed, $.cancelled]), 'run-finished'),
        when($.task === 0, [require($.task0 === $.running, 'not-running'), set('task0', $.failed), set('status', $.failed)],
          [when($.task === 1, [require($.task1 === $.running, 'not-running'), set('task1', $.failed), set('status', $.failed)],
            [require($.task2 === $.running, 'not-running'), set('task2', $.failed), set('status', $.failed)])]),
      ], ['task']),
      on('TaskEvicted', ($) => [
        require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.failed, $.cancelled]), 'run-finished'),
        when($.task === 0, [require($.task0 === $.running, 'not-running'), set('task0', $.evicted), when($.task1 === $.evicted && $.task2 === $.evicted, [set('status', $.evicted)], [when($.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.running)])])],
          [when($.task === 1, [require($.task1 === $.running, 'not-running'), set('task1', $.evicted), when($.task0 === $.evicted && $.task2 === $.evicted, [set('status', $.evicted)], [when($.task0 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.running)])])],
            [require($.task2 === $.running, 'not-running'), set('task2', $.evicted), when($.task0 === $.evicted && $.task1 === $.evicted, [set('status', $.evicted)], [when($.task0 === $.failed || $.task1 === $.failed, [set('status', $.failed)], [set('status', $.running)])])])]),
      ], ['task']),
      on('TaskRequeued', ($) => [
        require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.failed, $.cancelled]), 'run-finished'),
        when($.task === 0, [require($.task0 === $.evicted, 'not-evicted'), set('task0', $.queued), when($.task1 === $.queued && $.task2 === $.queued, [set('status', $.queued)], [when($.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.running)])])],
          [when($.task === 1, [require($.task1 === $.evicted, 'not-evicted'), set('task1', $.queued), when($.task0 === $.queued && $.task2 === $.queued, [set('status', $.queued)], [when($.task0 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.running)])])],
            [require($.task2 === $.evicted, 'not-evicted'), set('task2', $.queued), when($.task0 === $.queued && $.task1 === $.queued, [set('status', $.queued)], [when($.task0 === $.failed || $.task1 === $.failed, [set('status', $.failed)], [set('status', $.running)])])])]),
      ], ['task']),
      on('Cancel', ($) => [
        require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.failed, $.cancelled]), 'run-finished'),
        require(isIn($.task0, [$.queued, $.running, $.evicted]) || isIn($.task1, [$.queued, $.running, $.evicted]) || isIn($.task2, [$.queued, $.running, $.evicted]), 'nothing-in-flight'),
        when(isIn($.task0, [$.queued, $.running, $.evicted]), [set('task0', $.cancelled)]),
        when(isIn($.task1, [$.queued, $.running, $.evicted]), [set('task1', $.cancelled)]),
        when(isIn($.task2, [$.queued, $.running, $.evicted]), [set('task2', $.cancelled)]),
        when($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
      ]),
      invariant('completed-only-when-all-completed', ($) => implies($.status === $.completed, $.task0 === $.completed && $.task1 === $.completed && $.task2 === $.completed)),
      invariant('failed-whenever-a-task-failed', ($) => implies($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, $.status === $.failed)),
      invariant('not-done-while-in-flight', ($) => implies(isIn($.task0, [$.queued, $.running, $.evicted]) || isIn($.task1, [$.queued, $.running, $.evicted]) || isIn($.task2, [$.queued, $.running, $.evicted]), !isIn($.status, [$.completed, $.cancelled]))),
      invariant('unstarted-is-pristine', ($) => implies(!$.started, $.status === $.queued && $.task0 === $.queued && $.task1 === $.queued && $.task2 === $.queued)),
    ],
  }),
]);
